callGraph.callee:
this.http
      .get<IListData<IDeficiencyMapDto>>(`${this.soilsUrl}/map-objects`)
      .pipe(
        tap((data) => {
          this.mapDataSubject.next(data.list);
        }),
        catchError((err) => {
          console.error("Could not load soil deficiencies for map", err);
          return of({ list: [], totalCount: 0 } as IListData<IDeficiencyMapDto>);
        }),
        shareReplay(),
      )
      .subscribe

this.http
      .get<IListData<IDeficiencyMapDto>>(`${this.watersUrl}/map-objects`)
      .pipe(
        tap((data) => {
          this.mapDataSubject.next(data.list);
        }),
        catchError((err) => {
          console.error("Could not load water deficiencies for map", err);
          return of({ list: [], totalCount: 0 } as IListData<IDeficiencyMapDto>);
        }),
        shareReplay(),
      )
      .subscribe

this.markerList$
      .pipe(
        map((list) => {
          if (list && list.length) {
            this.clearDeficienciesLayersFromMap();

            list.forEach((d) => {
              const radius = d.radiusAffected > 0 ? d.radiusAffected : 10;
              if (this.isWaterDeficiency(d)) {
                this.makeCircleMarker(
                  EMapLayer.WaterDeficiency,
                  { longitude: d.longitude, latitude: d.latitude },
                  "#4285f4",
                  this.getDeficiencyPopup(d),
                  radius,
                );
              } else {
                this.makeCircleMarker(
                  EMapLayer.SoilDeficiency,
                  { longitude: d.longitude, latitude: d.latitude },
                  "brown",
                  this.getDeficiencyPopup(d),
                  radius,
                );
              }
            });
          }
        }),
      )
      .subscribe

this.labsAPIService.mapLabs$
      .pipe(
        map((list) => {
          this.laboratoriesLayer.clearLayers();

          if (list && list.length > 0) {
            list.forEach((lab) => {
              this.makeIconMarker(
                EMapLayer.Laboratories,
                { longitude: lab.longitude, latitude: lab.latitude },
                this.labIcon,
                this.getLabPopup(lab),
              );
            });
          }
        }),
      )
      .subscribe

